import React, { useRef } from "react";
import Webcam from "react-webcam";

function CameraScanner({ onCapture, onCameraError }) {
  const webcamRef = useRef(null);

  const capture = () => {
    if (!webcamRef.current) {
      console.log("Webcam not ready");
      return;
    }

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      console.log("Captured image success:", !!imageSrc);

      if (imageSrc) {
        console.log("Sending captured image to pipeline...");
        onCapture(imageSrc);
      } else {
        if (onCameraError) {
          onCameraError("Unable to capture image from camera stream. Please try again.");
        }
      }
    } catch (err) {
      console.error("Capture failure:", err);
      if (onCameraError) {
        onCameraError(`Failed to take screenshot: ${err.message || err}`);
      }
    }
  };

  const handleUserMediaError = (err) => {
    console.error("Webcam media stream failure:", err);
    if (onCameraError) {
      onCameraError(
        "Camera stream blocked. Please grant camera permission in your browser settings to scan."
      );
    }
  };

  return (
    <div className="camera-scanner-container">
      <div className="webcam-wrapper">
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          screenshotQuality={0.92}
          onUserMediaError={handleUserMediaError}
          videoConstraints={{
            facingMode: "environment",
            width: { ideal: 1280 },
            height: { ideal: 720 }
          }}
          className="webcam-feed"
        />
        <div className="scanner-overlay-laser"></div>
      </div>

      <button className="scan-btn capture-btn glow-effect" onClick={capture}>
        📸 Scan Ingredients Label
      </button>
    </div>
  );
}

export default CameraScanner;
